      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-ui-appearance\",\n  \"author\": \"TQSY114514\",\n  \"version\": \"0.1.28\",\n  \"description\": \"Appearance customization plugin for DeepSeek Harness WebUI: theme palette, background image, transparency and blur over the --dsw-* token system\",\n  \"license\": \"MIT\",\n  \"type\": \"module\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/TQSY114514/dsh-ui-appearance.git\"\n  },\n  \"engines\": {\n    \"node\": \">=18\"\n  },\n  \"packageManager\": \"pnpm@10.34.5\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./invariant\": {\n      \"types\": \"./lib/invariant.d.ts\",\n      \"default\": \"./lib/invariant.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/client.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./src/*\": \"./src/*\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"cordis.patch.yml\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-store\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-theme\",\n        \"@deepseek-ai/dsh-client-ui-primitives\",\n        \"@deepseek-ai/dsh-client-ui-slots\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"bundle\": \"tsdown --config tsdown.standalone.config.ts\",\n    \"watch\": \"tsdown --config tsdown.standalone.config.ts --watch\",\n    \"prepare\": \"tsdown --config tsdown.standalone.config.ts\",\n    \"test\": \"vitest run\",\n    \"typecheck\": \"tsc --noEmit\"\n  },\n  \"dependencies\": {\n    \"clsx\": \"^2.0.0\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"*\",\n    \"@deepseek-ai/dsh-api-remotes\": \"*\",\n    \"@deepseek-ai/dsh-client-connection\": \"*\",\n    \"@deepseek-ai/dsh-client-locale\": \"*\",\n    \"@deepseek-ai/dsh-client-runtime\": \"*\",\n    \"@deepseek-ai/dsh-client-store\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"*\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"*\",\n    \"@deepseek-ai/dsh-invariants\": \"*\",\n    \"@deepseek-ai/dsh-settings\": \"*\",\n    \"@deepseek-ai/schemastery\": \"*\",\n    \"react\": \"^18.2.0\"\n  },\n  \"peerDependenciesMeta\": {\n    \"@deepseek-ai/cordis\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-api-remotes\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-connection\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-locale\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-runtime\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-store\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-primitives\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-slots\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-client-ui-theme\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-invariants\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/dsh-settings\": {\n      \"optional\": true\n    },\n    \"@deepseek-ai/schemastery\": {\n      \"optional\": true\n    }\n  },\n  \"devDependencies\": {\n    \"@testing-library/dom\": \"^10.4.1\",\n    \"@testing-library/react\": \"^16.3.3\",\n    \"@types/react\": \"~18.3.1\",\n    \"fake-indexeddb\": \"^6.2.5\",\n    \"jsdom\": \"^31.0.0\",\n    \"lightningcss\": \"^1.32.0\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.3.1\",\n    \"tsdown\": \"^0.23.0\",\n    \"typescript\": \"^5.5.0\",\n    \"unrun\": \"^0.3.1\",\n    \"vitest\": \"^4.1.12\"\n  },\n  \"pnpm\": {\n    \"overrides\": {\n      \"source-map-js\": \">=1.2.2\",\n      \"vite\": \"^8.2.4\",\n      \"@vitest/mocker\": \"^4.1.12\"\n    }\n  }\n}\n"
    },
    {
      "path": "cordis.patch.yml",
      "content": "# dsh-ui-appearance bundle patch: inserts the ui-appearance row into the web\n# plugin roster. The bundle is the official dsh plugin shape — install it with\n# `dsh plugin --profile <name> add <path-or-git-url>` and the row lands in the\n# browser roster plus the host Loader without any harness-repo edits. To\n# uninstall, remove the package (or `dsh plugin remove ui-appearance`).\n- insert:\n    - id: ui-appearance\n      name: 'dsh-ui-appearance'\n"
    },
    {
      "path": "tsdown.standalone.config.ts",
      "content": "/**\n * Standalone build preset for the appearance plugin — a self-contained port\n * of the harness repo's `packages/client/tsdown.client.ts`, so this package\n * builds OUTSIDE the deepseek-harness checkout (the dsh-web-ui skins' pattern:\n * `dsh plugin add <path-or-git-url>` runs `prepare` and produces lib/ with no\n * project references). Emits the node half (lib/index.js + lib/invariant.js)\n * from source and the browser bundle (lib/client.js) with the\n * `window.__ModuleLoader__.load` closure shape; CSS Modules are inlined by\n * lightningcss and injected as a loader-owned <style data-plugin-css> tag.\n */\nimport { readFile } from 'node:fs/promises'\nimport { existsSync } from 'node:fs'\nimport { basename, dirname, relative, resolve as resolvePath, sep } from 'node:path'\nimport { fileURLToPath } from 'node:url'\nimport type { UserConfig } from 'tsdown'\nimport { transform } from 'lightningcss'\n\n/** The shell's frozen module table (mirrors packages/client/web/src/platform.ts). */\nconst PLATFORM_MODULES = [\n  'react', 'react/jsx-runtime', 'react-dom', 'react-dom/client', '@deepseek-ai/cordis',\n  '@deepseek-ai/dsh-client-ui-slots',\n  '@deepseek-ai/dsh-client-web-react',\n  '@deepseek-ai/dsh-client-ui-primitives',\n  '@deepseek-ai/dsh-client-ui-attachment',\n  '@deepseek-ai/dsh-client-schema-form',\n] as const\n\n/** Documented runtime exemption: the snapshot-store engine lives in dsh-client-store. */\nconst RUNTIME_STORE_EXEMPTION = '@deepseek-ai/dsh-client-store'\n\n/** Vendored framework libraries the client bundle inlines. */\nconst VENDORED_LIBRARY = /^@deepseek-ai\\/(cosmokit|schemastery)(\\/|$)/\n\n/** Wire/type layers a client bundle may inline (none used by this plugin). */\nconst INLINE_SAFE = /^@deepseek-ai\\/dsh-(host-apiproxy|session|llm|tools|brand)(\\/|$)/\n\n/** Externals resolved from the loader module table. */\nconst CLIENT_EXTERNALS: readonly string[] = [...PLATFORM_MODULES, RUNTIME_STORE_EXEMPTION]\n\nconst PACKAGE_ID = 'dsh-ui-appearance'\n\nconst CSS_VIRTUAL_PREFIX = '\\0dsh-css:'\nconst CSS_VIRTUAL_SUFFIX = '.mjs'\n\nconst REPOSITORY_ROOT = fileURLToPath(new URL('.', import.meta.url))\n\n/** Rebase a physical lib-relative source onto a browser URL mirroring the repository directories. */\nfunction browserSourcePath(source: string, sourcemapPath: string): string {\n  if (!source.startsWith('.')) return source\n  const physicalSource = resolvePath(dirname(sourcemapPath), source)\n  const repositoryPath = relative(REPOSITORY_ROOT, physicalSource).split(sep).join('/')\n  return repositoryPath.startsWith('packages/') ? `../../../${repositoryPath}` : source\n}\n\n/** Bundle purity gate: every @deepseek-ai value import must be a platform module or inline-safe. */\nconst purityGate = {\n  name: 'dsh-client-bundle-purity',\n  resolveId(source: string) {\n    if (!source.startsWith('@deepseek-ai/')) return null\n    if (CLIENT_EXTERNALS.includes(source)) return null\n    if (VENDORED_LIBRARY.test(source)) return null\n    if (INLINE_SAFE.test(source)) return null\n    throw new Error(\n      `client bundle purity: \"${source}\" is not a platform module or inline-safe wire layer — `\n      + 'cross-plugin value imports are forbidden; collaborate through cordis services (type-only imports are erased and never reach this gate)',\n    )\n  },\n}\n\n/** CSS Modules: compile with lightningcss and inject a loader-owned <style> tag. */\nconst cssModulesInline = {\n  name: 'dsh-css-modules-inline',\n  resolveId(source: string, importer: string | undefined) {\n    if (!source.endsWith('.module.css')) return null\n    const abs = importer !== undefined ? sourceAssetPath(source, importer) : source\n    return CSS_VIRTUAL_PREFIX + abs + CSS_VIRTUAL_SUFFIX\n  },\n  async load(this: { addWatchFile: (id: string) => void }, virtualId: string) {\n    if (!virtualId.startsWith(CSS_VIRTUAL_PREFIX)) return null\n    const fileId = virtualId.slice(CSS_VIRTUAL_PREFIX.length, -CSS_VIRTUAL_SUFFIX.length)\n    this.addWatchFile(fileId)\n    const source = await readFile(fileId)\n    const { code, exports: cssExports } = transform({\n      filename: fileId,\n      code: source,\n      cssModules: { pattern: '[hash]_[local]' },\n      minify: true,\n    })\n    const classMap: Record<string, string> = {}\n    for (const [local, exp] of Object.entries(cssExports ?? {})) classMap[local] = exp.name\n    return [\n      `const css = ${JSON.stringify(code.toString())};`,\n      `const tagId = ${JSON.stringify(`${PACKAGE_ID}/${basename(fileId)}`)};`,\n      'if (typeof document !== \\'undefined\\' && document.querySelector(\\'style[data-plugin-css=\\' + JSON.stringify(tagId) + \\']\\') === null) {',\n      '  const tag = document.createElement(\\'style\\');',\n      `  tag.dataset.plugin = ${JSON.stringify(PACKAGE_ID)};`,\n      '  tag.dataset.pluginCss = tagId;',\n      '  tag.textContent = css;',\n      '  document.head.appendChild(tag);',\n      '}',\n      `export default ${JSON.stringify(classMap)};`,\n    ].join('\\n')\n  },\n}\n\n/** Resolve an emitted JS asset import against its source-tree counterpart. */\nfunction sourceAssetPath(source: string, importer: string): string {\n  const emitted = resolvePath(dirname(importer), source)\n  if (existsSync(emitted)) return emitted\n  const marker = `${sep}lib${sep}types${sep}`\n  const boundary = emitted.indexOf(marker)\n  if (boundary < 0) return emitted\n  return resolvePath(emitted.slice(0, boundary), 'src', emitted.slice(boundary + marker.length))\n}\n\n/** Node half: bundled straight from source, deps external (host provides them). */\nconst nodeConfig: UserConfig = {\n  name: PACKAGE_ID,\n  entry: { index: 'src/index.ts', invariant: 'src/invariant.ts' },\n  outDir: 'lib',\n  format: ['esm'],\n  platform: 'node',\n  target: 'es2024',\n  fixedExtension: false,\n  // Emits lib/index.d.ts + lib/invariant.d.ts (unresolved @deepseek-ai peers\n  // are externalized in declaration mode, so the host-provided types resolve\n  // at the consumer).\n  dts: true,\n  clean: false,\n  tsconfig: 'tsconfig.json',\n}\n\n/** Browser half: closure-factory artifact landing exactly at lib/client.js. */\nconst clientConfig: UserConfig = {\n  name: `${PACKAGE_ID}/client`,\n  entry: { client: 'src/client/index.ts' },\n  outDir: 'lib',\n  format: 'cjs',\n  platform: 'neutral',\n  inputOptions: {\n    platform: 'browser',\n  },\n  target: 'es2022',\n  // The CJS closure cannot get a tsdown-emitted declaration (peers are not\n  // installed here); types/client.d.ts mirrors the public surface instead.\n  // copy's `to` is a DIRECTORY (dest = to/<basename>), so omit it to land in\n  // outDir as lib/client.d.ts.\n  dts: false,\n  sourcemap: true,\n  clean: false,\n  tsconfig: 'tsconfig.json',\n  copy: [{ from: 'types/client.d.ts' }],\n  deps: {\n    neverBundle: [...CLIENT_EXTERNALS],\n    alwaysBundle: (id: string) => !CLIENT_EXTERNALS.includes(id),\n    onlyBundle: ['clsx'],\n  },\n  define: {\n    'process.env.NODE_ENV': JSON.stringify(process.env.NODE_ENV ?? 'production'),\n    'import.meta.env.MODE': JSON.stringify(process.env.NODE_ENV ?? 'production'),\n    'import.meta.env': JSON.stringify({ MODE: process.env.NODE_ENV ?? 'production' }),\n  },\n  plugins: [purityGate, cssModulesInline],\n  outputOptions: {\n    entryFileNames: 'client.js',\n    sourcemapPathTransform: browserSourcePath,\n    banner: `window.__ModuleLoader__.load({ id: ${JSON.stringify(PACKAGE_ID)}, factory: (require) => {`,\n    footer: 'return module.exports; } });',\n    intro: 'var module = { exports: {} }; var exports = module.exports;',\n  },\n}\n\nexport default [nodeConfig, clientConfig]\n"
    },
    {
      "path": "src/client/index.ts",
      "content": "/**\n * Appearance customization plugin, browser half. Persists the `ui-appearance`\n * settings section in localStorage (the harness settings gateway only exposes\n * its hard-coded product namespaces to browser clients, so a third-party\n * namespace cannot be written through the settings RPC), projects every\n * change onto the document through the DOM applier (theme token overrides +\n * background layer), and registers the customizer row into the settings\n * General section. Settings writes are synchronous: update the section,\n * persist it, publish to the store and the applier. Background media live in\n * IndexedDB as blobs (settings only carry record keys) and resolve\n * asynchronously inside the applier. Cross-tab sync rides the `storage`\n * event.\n */\nimport type { BoundActions } from '@deepseek-ai/dsh-client-ui-slots'\nimport type { ClientContext } from '@deepseek-ai/dsh-client-runtime/client'\n// Type-only: pulls the locale and theme Context merges plus the settings\n// slot declarations ('settings.general.item' lives in the settings domain's\n// client contract). No settings scope: the gateway refuses non-product\n// namespaces, so settings persist in localStorage instead.\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-theme/client'\nimport type { AppearanceCustomizerInjected } from './AppearanceCustomizerRow.tsx'\nimport { AppearanceCustomizerRow } from './AppearanceCustomizerRow.tsx'\nimport { createAppearanceRowStore } from './settings-store.ts'\nimport { en, zh, type AppearanceKey } from './locales.ts'\nimport {\n  APPEARANCE_ROLES, DEFAULT_SETTINGS, DEFAULT_LIGHT_THEME, DEFAULT_DARK_THEME, sanitizeSettings,\n  type AppearanceRole, type AppearanceSettings, type InvertibleRole, type ThemeMode,\n} from '../appearance-settings.ts'\nimport { APPEARANCE_PRESETS, LIGHT_PRESETS, DARK_PRESETS } from './tokens.ts'\nimport { AppearanceApplier } from './applier.ts'\nimport { deleteImage, saveImage } from './image-store.ts'\nimport { deleteVideo } from './video-store.ts'\n\nexport type { AppearanceCustomizerComponentProps, AppearanceCustomizerInjected } from './AppearanceCustomizerRow.tsx'\nexport type { AppearanceRowState } from './settings-store.ts'\nexport type { AppearanceKey } from './locales.ts'\nexport type { AppearanceSettings } from '../appearance-settings.ts'\n\n/** Namespace owning this feature's settings-row copy. */\nexport const SETTINGS_NS = 'settings.appearance'\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    /** The appearance customizer row's copy. */\n    'settings.appearance': AppearanceKey\n  }\n}\n\n/** Required services: slots/locale for the row, theme for token overrides. */\nexport const inject = ['slots', 'locale', 'theme']\n\n/** localStorage key holding the whole settings section. */\nexport const STORAGE_KEY = 'dsh-ui-appearance.settings'\n\n/**\n * Read the persisted section, tolerating a missing, corrupt, or out-of-schema\n * entry: parse failures fall back to the stock defaults, and every parsed\n * field is validated against the schema bounds before it reaches the UI.\n * @returns the stored settings, or the stock defaults.\n */\nfunction readStoredSettings(): AppearanceSettings {\n  try {\n    const raw = localStorage.getItem(STORAGE_KEY)\n    if (raw === null) return { ...DEFAULT_SETTINGS }\n    return sanitizeSettings(JSON.parse(raw))\n  } catch (_unreadableStorage) {\n    return { ...DEFAULT_SETTINGS }\n  }\n}\n\n/**\n * One-shot migration: move a legacy inline data-URL wallpaper into the\n * IndexedDB image store and swap the settings field to its record key.\n * Failures keep the legacy value — the applier passes inline data URLs\n * through untouched, so nothing breaks either way.\n * @param read - read the live backgroundImage token (detects races).\n * @param commitSwap - persist the swapped-in record key.\n */\nfunction migrateLegacyImage(read: () => string, commitSwap: (key: string) => void): void {\n  const legacy = read()\n  if (!legacy.startsWith('data:')) return\n  void (async (): Promise<void> => {\n    try {\n      const blob = await (await fetch(legacy)).blob()\n      const key = await saveImage(blob, 'background')\n      // The user picked another background while migrating: drop our record,\n      // their choice is already persisted.\n      if (read() !== legacy) {\n        void deleteImage(key)\n        return\n      }\n      commitSwap(key)\n    } catch (_migrationFailed) {\n      // Keep the legacy inline value; retry on the next load.\n    }\n  })()\n}\n\n/**\n * Client plugin body: load the persisted section, mount the DOM applier, and\n * register the customizer row into the General section.\n * @param ctx - client cordis context.\n */\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => ctx.locale.register(SETTINGS_NS, { zh, en }), 'ui-appearance: settings row dictionaries')\n\n  const store = createAppearanceRowStore()\n  let bound: BoundActions<typeof store> | undefined\n  let current: AppearanceSettings = readStoredSettings()\n  let revision = 0\n  let applier: AppearanceApplier | undefined\n  // Decode failures can fire during the initial apply, before the slot has\n  // bound the row's store; stash the latest state and replay it when bound.\n  let videoPlaybackError = false\n  // Token override rebuilds (applier.apply) are the expensive part of a\n  // commit. Drag-style writes fire on every pointermove / color-picker input,\n  // so coalesce rebuilds onto the animation frame: at most one rebuild per\n  // rendered frame, aligned with vsync. The trailing edge still applies the\n  // very last value one frame later, so a drag never drops its final position.\n  // localStorage and the store sync stay synchronous so swatches, React rows,\n  // and persistence never lag behind the drag.\n  let applyRaf: number | undefined\n  let applyPending = false\n\n  const scheduleApply = (): void => {\n    if (applyRaf !== undefined) {\n      applyPending = true\n      return\n    }\n    applyRaf = requestAnimationFrame(() => {\n      applyRaf = undefined\n      applyPending = false\n      applier?.apply(current)\n    })\n  }\n\n  /** Cancel any pending frame and apply the latest state right now. */\n  const flushApply = (): void => {\n    if (applyRaf !== undefined) {\n      cancelAnimationFrame(applyRaf)\n      applyRaf = undefined\n    }\n    applyPending = false\n    applier?.apply(current)\n  }\n\n  const publish = (): void => {\n    revision += 1\n    bound?.sync(current, revision)\n    scheduleApply()\n  }\n\n  // DOM applier: created once, retracts everything on dispose. Storage\n  // persistence is best-effort: ask the browser not to evict the IndexedDB\n  // media records under storage pressure (unsupported environments skip).\n  ctx.effect(() => {\n    try {\n      void navigator.storage?.persist?.().catch(() => { /* not grantable */ })\n    } catch (_storageUnsupported) {\n      // Environments without navigator.storage: nothing to persist anyway.\n    }\n    applier = new AppearanceApplier(ctx)\n    // The applier is the only place that learns a video failed to decode; push\n    // that onto the row's store so the background section can explain the\n    // blank background instead of staying silent.\n    applier.onVideoPlaybackError = failed => {\n      videoPlaybackError = failed\n      bound?.setVideoPlaybackError(failed)\n    }\n    applier.apply(current)\n    // One-shot migration of a legacy inline wallpaper into IndexedDB; the\n    // applier shows the inline value until the swap lands.\n    migrateLegacyImage(\n      () => current.backgroundImage,\n      key => {\n        current = { ...current, backgroundImage: key }\n        commit()\n        flushApply()\n      },\n    )\n    return () => {\n      if (applyRaf !== undefined) {\n        cancelAnimationFrame(applyRaf)\n        applyRaf = undefined\n        applyPending = false\n      }\n      applier?.dispose()\n      applier = undefined\n    }\n  }, 'ui-appearance: DOM applier')\n\n  // Cross-tab sync: another tab persisted a section change.\n  ctx.effect(() => {\n    const onStorage = (event: StorageEvent): void => {\n      if (event.key !== null && event.key !== STORAGE_KEY) return\n      current = readStoredSettings()\n      publish()\n    }\n    window.addEventListener('storage', onStorage)\n    return () => { window.removeEventListener('storage', onStorage) }\n  }, 'ui-appearance: storage sync')\n\n  const commit = (): void => {\n    try {\n      localStorage.setItem(STORAGE_KEY, JSON.stringify(current))\n    } catch (_storageQuota) {\n      // Quota exceeded (e.g. an oversized image): keep the in-memory state so\n      // this session still works; the change just does not survive a reload.\n    }\n    publish()\n  }\n  const set = (field: keyof AppearanceSettings, value: string | number | boolean): void => {\n    const patch = { ...current }\n    // The union key cannot be assigned through the keyed type (mixed string /\n    // number / boolean fields intersect to never), so write through an index view.\n    ;(patch as unknown as Record<string, string | number | boolean>)[field] = value\n    if (APPEARANCE_ROLES.includes(field as AppearanceRole)) {\n      const hex = typeof value === 'string' ? value : ''\n      patch.light = { ...patch.light, [field]: hex }\n      patch.dark = { ...patch.dark, [field]: hex }\n    } else if (field === 'preset') {\n      const presetId = typeof value === 'string' ? value : ''\n      patch.light = { ...patch.light, preset: presetId }\n      patch.dark = { ...patch.dark, preset: presetId }\n    } else if (field === 'sidebarAlpha') {\n      const alpha = typeof value === 'number' ? value : 1\n      patch.sidebarOpaque = alpha === 1\n    } else if (field === 'sidebarOpaque') {\n      const opaque = !!value\n      patch.sidebarAlpha = opaque ? 1 : patch.surfaceAlpha\n    }\n    current = patch\n    commit()\n  }\n  const setModeRole = (mode: ThemeMode, role: AppearanceRole, value: string): void => {\n    const patch = { ...current }\n    patch[mode] = {\n      ...patch[mode],\n      [role]: value,\n      preset: 'custom',\n      invert: {\n        ...patch[mode].invert,\n        accent: true,\n        background: false,\n      },\n    }\n    // Top-level role fields are a legacy mirror only: dual-mode writes must\n    // NOT pollute them, or the untouched mode falls back to this value via\n    // getRole() and shows the wrong color (e.g. light mode leaks dark edits).\n    patch.preset = 'custom'\n    current = patch\n    commit()\n  }\n  const setModeInvert = (mode: ThemeMode, role: InvertibleRole, value: boolean): void => {\n    const patch = { ...current }\n    patch[mode] = {\n      ...patch[mode],\n      invert: { ...patch[mode].invert, [role]: value },\n    }\n    current = patch\n    commit()\n    flushApply()\n  }\n  const setImage = (image: { url: string; imageDark: boolean } | null): void => {\n    const patch = { ...current }\n    // A replacement supersedes the previous record; drop it so repeated swaps\n    // cannot accumulate orphaned blobs (inline legacy data URLs need no\n    // cleanup — they never entered IndexedDB).\n    const old = patch.backgroundImage\n    if (old !== '' && !old.startsWith('data:') && old !== (image?.url ?? '')) {\n      void deleteImage(old)\n    }\n    patch.backgroundImage = image?.url ?? ''\n    patch.imageDark = image?.imageDark ?? false\n    // Image and video backgrounds are mutually exclusive.\n    if (image !== null) patch.backgroundVideo = ''\n    current = patch\n    commit()\n    flushApply()\n  }\n  const setVideo = (key: string | null): void => {\n    // A replacement supersedes the previous record; drop it now so repeated\n    // swaps cannot accumulate orphaned blobs in IndexedDB.\n    if (key !== null && key !== current.backgroundVideo && current.backgroundVideo !== '') {\n      void deleteVideo(current.backgroundVideo)\n    }\n    const patch = { ...current }\n    patch.backgroundVideo = key ?? ''\n    // Image and video backgrounds are mutually exclusive. Dropping the image\n    // also drops its IndexedDB record (legacy inline data URLs need none).\n    if (key !== null) {\n      const oldImage = patch.backgroundImage\n      if (oldImage !== '' && !oldImage.startsWith('data:')) void deleteImage(oldImage)\n      patch.backgroundImage = ''\n      patch.imageDark = false\n    }\n    current = patch\n    commit()\n    flushApply()\n  }\n  const applyModePreset = (mode: ThemeMode, id: string): void => {\n    const catalog = mode === 'light' ? LIGHT_PRESETS : DARK_PRESETS\n    const preset = catalog.find(candidate => candidate.id === id)\n      ?? APPEARANCE_PRESETS.find(candidate => candidate.id === id)\n    if (preset === undefined) return\n    const updatedTheme = { ...current[mode], preset: id }\n    if (id === 'default') {\n      for (const role of APPEARANCE_ROLES) updatedTheme[role] = ''\n    } else {\n      for (const [role, hex] of Object.entries(preset.colors)) {\n        if (hex === undefined) continue\n        updatedTheme[role as AppearanceRole] = hex\n      }\n    }\n    const patch = { ...current, [mode]: updatedTheme }\n    patch.preset = id\n    current = patch\n    commit()\n    flushApply()\n  }\n  const applyModeColors = (mode: ThemeMode, colors: Partial<Record<AppearanceRole, string>>): void => {\n    const entries = Object.entries(colors).filter(\n      (entry): entry is [string, string] =>\n        APPEARANCE_ROLES.includes(entry[0] as AppearanceRole) && entry[1] !== undefined && entry[1] !== '',\n    )\n    if (entries.length === 0) return\n    const updatedTheme = { ...current[mode], preset: 'custom' }\n    for (const [role, hex] of entries) updatedTheme[role as AppearanceRole] = hex\n    const patch = { ...current, [mode]: updatedTheme }\n    patch.preset = 'custom'\n    current = patch\n    commit()\n    flushApply()\n  }\n  const resetMode = (mode: ThemeMode): void => {\n    const defaultMode = mode === 'light' ? DEFAULT_LIGHT_THEME : DEFAULT_DARK_THEME\n    const patch = { ...current, [mode]: { ...defaultMode, preset: 'default', invert: { ...defaultMode.invert } } }\n    patch.preset = 'default'\n    current = patch\n    commit()\n    flushApply()\n  }\n  const applyPreset = (id: string): void => {\n    applyModePreset('dark', id)\n  }\n  // One commit for a whole batch of role colors (scheme import), instead of a\n  // per-role set() storm of localStorage writes and override rebuilds.\n  const applyColors = (colors: Partial<Record<AppearanceRole, string>>): void => {\n    applyModeColors('dark', colors)\n  }\n  const resetAll = (): void => {\n    const oldImage = current.backgroundImage\n    if (oldImage !== '' && !oldImage.startsWith('data:')) {\n      void deleteImage(oldImage)\n    }\n    const oldVideo = current.backgroundVideo\n    if (oldVideo !== '') {\n      void deleteVideo(oldVideo)\n    }\n    current = {\n      ...DEFAULT_SETTINGS,\n      preset: 'default',\n      light: { ...DEFAULT_LIGHT_THEME, invert: { ...DEFAULT_LIGHT_THEME.invert } },\n      dark: { ...DEFAULT_DARK_THEME, invert: { ...DEFAULT_DARK_THEME.invert } },\n    }\n    commit()\n    flushApply()\n  }\n\n  const injected = (actions: BoundActions<typeof store>): AppearanceCustomizerInjected => {\n    bound = actions\n    // Push the initial section so the row renders the persisted values.\n    publish()\n    // Replay a decode failure that landed before the row's store was bound.\n    if (videoPlaybackError) actions.setVideoPlaybackError(true)\n    return {\n      set, setModeRole, setModeInvert, setImage, setVideo,\n      applyModePreset, applyModeColors, resetMode,\n      applyPreset, applyColors, resetAll,\n    }\n  }\n\n  ctx.slots.inject('settings.general.item', () => ctx.slots.register({\n    name: 'settings.general.item',\n    id: 'appearance-custom',\n    order: 1000,\n    store,\n    locale: SETTINGS_NS,\n    inject: injected,\n  }, AppearanceCustomizerRow))\n}\n"
