NavActive, flipButtonElevated)\n    bakeControlTranslucent('--dsw-alias-button-ghost-active-fill', controlNavActive, flipButtonElevated)\n    bakeControlTranslucent('--dsw-alias-button-ghost-active-hover', controlButtonHover, flipButtonFloatingHover)\n    bakeControlTranslucent('--dsw-alias-markdown-tag', controlNavActive, flipButtonFloating)\n    translucent('--dsw-specific-tip', undefined, undefined, flipMod[0], flipMod[1])\n  }\n\n  if (surfaceAlpha < 1 || inputAlpha < 1) {\n    bakeAccent('--dsw-alias-button-primary-fill', inputAlpha)\n    bakeAccent('--dsw-alias-button-info-fill', inputAlpha)\n\n    const bakeInputHover = (token: string, derivedLight?: string, derivedDark?: string): void => {\n      const stock = DEFAULT_SURFACE_COLORS[token]\n      const l = derivedLight ?? stock?.light\n      const d = derivedDark ?? stock?.dark\n      if (l !== undefined && d !== undefined) {\n        emit(token, withAlpha(l, inputAlpha), withAlpha(d, inputAlpha))\n      }\n    }\n    bakeInputHover('--dsw-alias-button-info-hover', lightInfoHover, darkInfoHover)\n    bakeInputHover('--dsw-alias-button-primary-hover', lightPrimaryHover, darkPrimaryHover)\n\n    const plusBaseL = controlButtonFill?.[0] ?? flipButtonFloating[0]\n    const plusBaseD = controlButtonFill?.[1] ?? flipButtonFloating[1]\n    if (plusBaseL !== undefined || plusBaseD !== undefined) {\n      const pL = plusBaseL ?? DEFAULT_SURFACE_COLORS['--dsw-specific-selector'].light\n      const pD = plusBaseD ?? DEFAULT_SURFACE_COLORS['--dsw-specific-selector'].dark\n      emit('--dsw-specific-selector', withAlpha(pL, inputAlpha), withAlpha(pD, inputAlpha))\n    } else {\n      bakeAlpha('--dsw-specific-selector', undefined, undefined, undefined, undefined, inputAlpha)\n    }\n  }\n\n  // In opaque mode (surfaceAlpha === 1), interactive hover, solid hover, and\n  // active tab/chip tokens must emit concrete static hex values (AGENTS.md hover\n  // mechanism) rather than falling back to host's stock 6%–14% opacity, which looks\n  // inconsistent when transitioning between translucent and opaque modes.\n  const hoverL = controlButtonHover?.[0] ?? flipButtonFloatingHover[0] ?? DEFAULT_SURFACE_COLORS['--dsw-alias-interactive-bg-hover'].light\n  const hoverD = controlButtonHover?.[1] ?? flipButtonFloatingHover[1] ?? DEFAULT_SURFACE_COLORS['--dsw-alias-interactive-bg-hover'].dark\n  if (!tokens['--dsw-alias-interactive-bg-hover']) {\n    emit('--dsw-alias-interactive-bg-hover', hoverL, hoverD)\n  }\n  if (!tokens['--dsw-alias-interactive-bg-hover-solid']) {\n    emit('--dsw-alias-interactive-bg-hover-solid', hoverL, hoverD)\n  }\n  const activeL = controlNavActive?.[0] ?? flipButtonElevated[0] ?? DEFAULT_SURFACE_COLORS['--dsw-alias-interactive-bg-active'].light\n  const activeD = controlNavActive?.[1] ?? flipButtonElevated[1] ?? DEFAULT_SURFACE_COLORS['--dsw-alias-interactive-bg-active'].dark\n  if (!tokens['--dsw-alias-interactive-bg-active']) {\n    emit('--dsw-alias-interactive-bg-active', activeL, activeD)\n  }\n  const tagL = controlNavActive?.[0] ?? flipButtonFloating[0] ?? DEFAULT_SURFACE_COLORS['--dsw-alias-markdown-tag'].light\n  const tagD = controlNavActive?.[1] ?? flipButtonFloating[1] ?? DEFAULT_SURFACE_COLORS['--dsw-alias-markdown-tag'].dark\n  if (!tokens['--dsw-alias-markdown-tag']) {\n    emit('--dsw-alias-markdown-tag', tagL, tagD)\n  }\n\n  return tokens\n}\n\n/** One shipped preset: a starter set of role colors. */\nexport interface AppearancePreset {\n  /** Preset id (persisted in the `preset` field). */\n  id: string\n  /** Role colors; absent roles keep the user's current value. */\n  colors: Partial<Record<AppearanceRole, string>>\n  /** Supported mode for this preset: 'light', 'dark', or 'both' (default 'both'). */\n  mode?: 'light' | 'dark' | 'both'\n}\n\n/** Light mode starter presets. */\nexport const LIGHT_PRESETS: readonly AppearancePreset[] = [\n  { id: 'default', colors: {}, mode: 'light' },\n  {\n    id: 'dawn',\n    colors: {\n      accent: '#d97706',\n      background: '#fbfaf8',\n      panel: '#f4f1ea',\n      input: '#ffffff',\n      text: '#292524',\n      border: '#e7e5e4',\n    },\n    mode: 'light',\n  },\n  {\n    id: 'sky',\n    colors: {\n      accent: '#0284c7',\n      background: '#f0f9ff',\n      panel: '#e0f2fe',\n      input: '#ffffff',\n      text: '#0f172a',\n      border: '#bae6fd',\n    },\n    mode: 'light',\n  },\n  {\n    id: 'mint',\n    colors: {\n      accent: '#059669',\n      background: '#f0fdf4',\n      panel: '#dcfce7',\n      input: '#ffffff',\n      text: '#14532d',\n      border: '#bbf7d0',\n    },\n    mode: 'light',\n  },\n  {\n    id: 'sakura',\n    colors: {\n      accent: '#db2777',\n      background: '#fdf2f8',\n      panel: '#fce7f3',\n      input: '#ffffff',\n      text: '#831843',\n      border: '#fbcfe8',\n    },\n    mode: 'light',\n  },\n  {\n    id: 'clay',\n    colors: {\n      accent: '#4b5563',\n      background: '#f9fafb',\n      panel: '#f3f4f6',\n      input: '#ffffff',\n      text: '#111827',\n      border: '#e5e7eb',\n    },\n    mode: 'light',\n  },\n]\n\n/** Dark mode starter presets. */\nexport const DARK_PRESETS: readonly AppearancePreset[] = [\n  { id: 'default', colors: {}, mode: 'dark' },\n  {\n    id: 'midnight',\n    colors: {\n      accent: '#7c9cff',\n      background: '#1b1e2c',\n      panel: '#232737',\n      input: '#202435',\n      text: '#e6e9f4',\n      border: '#343a52',\n    },\n    mode: 'dark',\n  },\n  {\n    id: 'ocean',\n    colors: {\n      accent: '#4fc3f7',\n      background: '#0c2231',\n      panel: '#12303f',\n      input: '#0f2a38',\n      text: '#e1f1fa',\n      border: '#1e455c',\n    },\n    mode: 'dark',\n  },\n  {\n    id: 'forest',\n    colors: {\n      accent: '#81c784',\n      background: '#12241b',\n      panel: '#183026',\n      input: '#152b21',\n      text: '#e7f0ea',\n      border: '#2b4637',\n    },\n    mode: 'dark',\n  },\n  {\n    id: 'rose',\n    colors: {\n      accent: '#f48fb1',\n      background: '#291a21',\n      panel: '#36232d',\n      input: '#2e1f27',\n      text: '#f7e9ee',\n      border: '#4a3340',\n    },\n    mode: 'dark',\n  },\n  {\n    id: 'monochrome',\n    colors: {\n      accent: '#b4b4b9',\n      background: '#17171a',\n      panel: '#202025',\n      input: '#1c1c20',\n      text: '#eeeef0',\n      border: '#333338',\n    },\n    mode: 'dark',\n  },\n]\n\n/** All shipped presets; combining dark and light catalogs. */\nexport const APPEARANCE_PRESETS: readonly AppearancePreset[] = [\n  ...DARK_PRESETS,\n  ...LIGHT_PRESETS.filter(candidate => candidate.id !== 'default'),\n]\n"
    },
