      "path": "src/client/AppearanceCustomizerRow.tsx",
      "content": "/**\n * The Appearance customizer row registered into the General section item slot\n * (below ui-theme's Appearance preference row): preset chips, eight color\n * pickers, the background upload/drop zone with opacity and blur sliders, and\n * the interface transparency / glass sliders. All writes go through the\n * injected face; the scope round-trip reconciles.\n */\nimport { useEffect, useRef, useState, type ChangeEvent, type DragEvent } from 'react'\nimport clsx from 'clsx'\nimport {\n  DisclosureRow,\n  IconPersonalizationOutline16,\n  IconPersonalizationOutlineMedium,\n  IconPersonalizationOutlineRegular,\n} from '@deepseek-ai/dsh-client-ui-primitives'\nimport type { PropsLocale, PropsRuntime, PropsStore } from '@deepseek-ai/dsh-client-ui-slots'\nimport { APPEARANCE_ROLES, type AppearanceRole, type AppearanceSettings, type InvertibleRole, type ThemeMode } from '../appearance-settings.ts'\nimport { formatHex, isHexColor, parseHex } from './color.ts'\nimport { ACCEPTED_IMAGE_TYPES, derivePalette, MAX_INPUT_BYTES, prepareImage } from './image.ts'\nimport { getImage, saveImage } from './image-store.ts'\nimport { ACCEPTED_VIDEO_TYPES, deleteVideo, isVideoFile, MAX_VIDEO_BYTES, saveVideo } from './video-store.ts'\nimport { classifyUrl, loadImageFromUrl, loadVideoFromUrl, urlToName, UrlLoadFailure, type UrlLoadError } from './url-load.ts'\nimport { exportColorScheme, parseColorScheme } from './color-scheme.ts'\nimport {\n  APPEARANCE_PRESETS, LIGHT_PRESETS, DARK_PRESETS,\n  BACKGROUND_BLUR_MAX, EMPHASIS_ALPHA_MAX, EMPHASIS_ALPHA_MIN, GLASS_BLUR_MAX,\n} from './tokens.ts'\nimport type { AppearanceKey } from './locales.ts'\nimport type { createAppearanceRowStore } from './settings-store.ts'\nimport css from './AppearanceCustomizerRow.module.css'\n\n/** Injected business face: the row's whole write path. */\nexport interface AppearanceCustomizerInjected {\n  /** Update one settings field (optimistic + debounced persistence). */\n  set: (field: keyof AppearanceSettings, value: string | number | boolean) => void\n  /** Update one role color in a specific mode (light or dark). */\n  setModeRole?: (mode: ThemeMode, role: AppearanceRole, value: string) => void\n  /** Toggle foreground auto-inversion for one surface role in a specific mode. */\n  setModeInvert?: (mode: ThemeMode, role: InvertibleRole, value: boolean) => void\n  /** Set or clear the background image (null removes it). */\n  setImage: (image: { url: string; imageDark: boolean } | null) => void\n  /** Set or clear the background video by its IndexedDB record key. */\n  setVideo: (key: string | null) => void\n  /** Apply one shipped preset to a specific mode. */\n  applyModePreset?: (mode: ThemeMode, id: string) => void\n  /** Apply a batch of role colors to a specific mode in one write. */\n  applyModeColors?: (mode: ThemeMode, colors: Partial<Record<AppearanceRole, string>>) => void\n  /** Reset one mode's settings to default. */\n  resetMode?: (mode: ThemeMode) => void\n  /** Apply one shipped preset (colors only). */\n  applyPreset: (id: string) => void\n  /** Apply a batch of role colors in one write (scheme import). */\n  applyColors: (colors: Partial<Record<AppearanceRole, string>>) => void\n  /** Restore every setting to its stock value. */\n  resetAll: () => void\n}\n\n/** Full component props: runtime share + store share + locale seat + injected face. */\nexport type AppearanceCustomizerComponentProps =\n  PropsRuntime<'settings.general.item'> & PropsStore<ReturnType<typeof createAppearanceRowStore>>\n  & PropsLocale<'settings.appearance'> & AppearanceCustomizerInjected\n\n/** Stock display color per role and mode, shown when the role is unset\n * so the swatch always mirrors what the theme actually uses. */\nconst STOCK_ROLE_COLORS: Record<ThemeMode, Record<AppearanceRole, string>> = {\n  light: {\n    accent: '#4176e6',\n    background: '#ffffff',\n    panel: '#ffffff',\n    input: '#ffffff',\n    text: '#0f1115',\n    border: '#d9dde3',\n  },\n  dark: {\n    accent: '#4176e6',\n    background: '#151517',\n    panel: '#232324',\n    input: '#2c2c2e',\n    text: '#fafaf9',\n    border: '#333338',\n  },\n}\n\n/**\n * Personalization icon adapter: DSH >= 0.1.7-rc.1 replaced size-suffixed\n * icon exports (`IconPersonalizationOutline16`) with weight-suffixed ones\n * (`IconPersonalizationOutlineRegular` / `IconPersonalizationOutlineMedium`).\n * Resolve whichever the host provides and fall back to an inline SVG so the\n * row never crashes under a future host icon rename.\n */\nfunction PersonalizationIcon() {\n  const Icon = IconPersonalizationOutlineRegular\n    ?? IconPersonalizationOutlineMedium\n    ?? IconPersonalizationOutline16\n  if (typeof Icon === 'function') return <Icon size={16} />\n  return (\n    <svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">\n      <circle cx=\"8\" cy=\"8\" r=\"6\" />\n      <circle cx=\"6\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\" />\n      <circle cx=\"10\" cy=\"6.5\" r=\"0.8\" fill=\"currentColor\" />\n      <circle cx=\"8\" cy=\"10\" r=\"0.8\" fill=\"currentColor\" />\n    </svg>\n  )\n}\n\nfunction SunIcon() {\n  return (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">\n      <circle cx=\"12\" cy=\"12\" r=\"4\" />\n      <path d=\"M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M6.34 17.66l-1.41 1.41M19.07 4.93l-1.41 1.41\" />\n    </svg>\n  )\n}\n\nfunction MoonIcon() {\n  return (\n    <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\" aria-hidden=\"true\">\n      <path d=\"M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z\" />\n    </svg>\n  )\n}\n\n/** Freeze host transitions while a control is being dragged so rapid token\n * updates render at full frame rate (see the applier stylesheet rule). */\nconst beginDragFreeze = (): void => { document.body.setAttribute('data-dsw-sliding', '') }\nconst endDragFreeze = (): void => { document.body.removeAttribute('data-dsw-sliding') }\n\n/** One color field row: native swatch + hex text input. */\nfunction ColorField(props: {\n  label: string\n  value: string\n  stock: string\n  onChange: (hex: string) => void\n}) {\n  const { label, value, stock, onChange } = props\n  const effectiveValue = value === '' ? stock : value\n  const [draft, setDraft] = useState(effectiveValue)\n  useEffect(() => { setDraft(effectiveValue) }, [effectiveValue])\n  const commit = (): void => {\n    const hex = draft.trim().toLowerCase()\n    if (hex === effectiveValue.toLowerCase()) return\n    if (hex === '' || hex === stock.toLowerCase()) {\n      onChange('')\n      setDraft(stock)\n      return\n    }\n    if (isHexColor(hex)) {\n      onChange(hex)\n    } else {\n      setDraft(effectiveValue)\n    }\n  }\n  return (\n    <label className={css.colorField}>\n      <span className={css.colorLabel}>{label}</span>\n      <span className={css.colorSwatch} style={{ backgroundColor: effectiveValue }}>\n        <input\n          type=\"color\"\n          className={css.colorSwatchInput}\n          aria-label={`${label} (color picker)`}\n          value={effectiveValue}\n          onPointerDown={beginDragFreeze}\n          onPointerCancel={endDragFreeze}\n          onBlur={endDragFreeze}\n          onChange={event => { onChange(event.target.value) }}\n        />\n      </span>\n      <input\n        type=\"text\"\n        className={css.colorHex}\n        aria-label={`${label} (hex)`}\n        placeholder={stock}\n        value={draft}\n        spellCheck={false}\n        onChange={event => { setDraft(event.target.value) }}\n        onBlur={commit}\n        onKeyDown={event => { if (event.key === 'Enter') commit() }}\n      />\n    </label>\n  )\n}\n\n/** One labeled slider with a formatted value readout. */\nfunction Slider(props: {\n  label: string\n  value: number\n  min: number\n  max: number\n  step: number\n  format: (value: number) => string\n  onChange: (value: number) => void\n}) {\n  const { label, value, min, max, step, format, onChange } = props\n  return (\n    <div className={css.sliderRow}>\n      <span className={css.sliderLabel}>{label}</span>\n      <input\n        type=\"range\"\n        className={css.slider}\n        aria-label={label}\n        min={min}\n        max={max}\n        step={step}\n        value={value}\n        onPointerDown={beginDragFreeze}\n        onPointerUp={endDragFreeze}\n        onPointerCancel={endDragFreeze}\n        onChange={event => { onChange(Number(event.target.value)) }}\n      />\n      <span className={css.sliderValue}>{format(value)}</span>\n    </div>\n  )\n}\n\n/** Map a remote-load failure code to the localized message key. */\nfunction urlErrorText(code: UrlLoadError, t: (key: AppearanceKey) => string): string {\n  const key: AppearanceKey = `background.urlError.${code}` as AppearanceKey\n  return t(key)\n}\n\n/** Map a local-read failure code to the localized message key ('read' keeps\n * the base key as the catch-all). A missing sub-key must never render as a\n * blank hint, so fall back to the catch-all message instead. */\nfunction localErrorText(prefix: 'background.readError' | 'background.videoError', code: 'type' | 'size' | 'read', t: (key: AppearanceKey) => string): string {\n  const key: AppearanceKey = (code === 'read' ? prefix : `${prefix}.${code}`) as AppearanceKey\n  const text = t(key)\n  return text === '' || text === key ? t(prefix) : text\n}\n\n/** Thumbnail for the stored wallpaper. Legacy tokens are inline data URLs\n * (rendered directly); current tokens are IndexedDB keys resolved to object\n * URLs, revoked when the token changes or the row unmounts. */\nfunction BackgroundThumb(props: { token: string }) {\n  const { token } = props\n  const [src, setSrc] = useState('')\n  useEffect(() => {\n    if (token === '') {\n      setSrc('')\n      return\n    }\n    if (token.startsWith('data:')) {\n      setSrc(token)\n      return\n    }\n    let stale = false\n    let objectUrl: string | undefined\n    void getImage(token).then(blob => {\n      if (blob === undefined || stale) return\n      objectUrl = URL.createObjectURL(blob)\n      setSrc(objectUrl)\n    })\n    return () => {\n      stale = true\n      if (objectUrl !== undefined) URL.revokeObjectURL(objectUrl)\n    }\n  }, [token])\n  if (src === '') return null\n  return <img className={css.thumb} src={src} alt=\"\" />\n}\n\n/**\n * Render the appearance customizer row.\n * @param props - composed slot props.\n * @returns the row element tree.\n */\nexport function AppearanceCustomizerRow({\n  t, useStore, set, setModeRole, setImage, setVideo,\n  applyModePreset, applyModeColors, resetMode,\n  applyPreset, applyColors, resetAll,\n}: AppearanceCustomizerComponentProps) {\n  const settings = useStore(s => s.settings)\n  const videoPlaybackError = useStore(s => s.videoPlaybackError)\n  const [open, setOpen] = useState(false)\n  const [reading, setReading] = useState(false)\n  const [readError, setReadError] = useState<'type' | 'size' | 'read' | null>(null)\n  const [videoReading, setVideoReading] = useState(false)\n  const [videoError, setVideoError] = useState<'type' | 'size' | 'read' | null>(null)\n  const [dragging, setDragging] = useState(false)\n  const [urlDraft, setUrlDraft] = useState('')\n  const [urlReading, setUrlReading] = useState(false)\n  const [urlError, setUrlError] = useState<UrlLoadError | null>(null)\n  const [schemeOpen, setSchemeOpen] = useState(false)\n  const [schemeDraft, setSchemeDraft] = useState('')\n  const [schemeError, setSchemeError] = useState(false)\n  const [exported, setExported] = useState(false)\n  const exportTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)\n  const fileRef = useRef<HTMLInputElement | null>(null)\n  const videoRef = useRef<HTMLInputElement | null>(null)\n\n  useEffect(() => () => {\n    if (exportTimerRef.current !== null) clearTimeout(exportTimerRef.current)\n  }, [])\n\n  const detectHostDark = (): boolean => {\n    if (typeof document === 'undefined') return false\n    return document.body?.hasAttribute('data-ds-dark-theme')\n      || document.documentElement?.hasAttribute('data-ds-dark-theme')\n      || (document.documentElement?.getAttribute('data-theme') === 'dark')\n  }\n\n  const [hostDarkMode, setHostDarkMode] = useState(detectHostDark)\n  const currentHostMode: ThemeMode = hostDarkMode ? 'dark' : 'light'\n  const [activeMode, setActiveMode] = useState<ThemeMode>(() => (detectHostDark() ? 'dark' : 'light'))\n\n  useEffect(() => {\n    const update = (): void => { setHostDarkMode(detectHostDark()) }\n    const observer = new MutationObserver(update)\n    if (document.body) {\n      observer.observe(document.body, { attributes: true, attributeFilter: ['data-ds-dark-theme', 'data-theme', 'class'] })\n    }\n    if (document.documentElement) {\n      observer.observe(document.documentElement, { attributes: true, attributeFilter: ['data-ds-dark-theme', 'data-theme', 'class'] })\n    }\n    const mql = window.matchMedia?.('(prefers-color-scheme: dark)')\n    mql?.addEventListener?.('change', update)\n    return () => {\n      observer.disconnect()\n      mql?.removeEventListener?.('change', update)\n    }\n  }, [])\n\n  // Keep the edited mode in sync with the host's actual theme mode so the\n  // palette swatches always reflect the colors currently on screen. The user\n  // can still manually switch tabs to edit the other mode; this only fires\n  // when the host genuinely changes (light <-> dark / follow-system).\n  useEffect(() => {\n    setActiveMode(hostDarkMode ? 'dark' : 'light')\n  }, [hostDarkMode])\n\n  const currentModeTheme = settings[activeMode] ?? (activeMode === 'light' ? settings.light : settings.dark)\n  const activePreset = currentModeTheme?.preset || (activeMode === 'dark' ? settings.preset : '')\n  const presetsCatalog = activeMode === 'light' ? LIGHT_PRESETS : DARK_PRESETS\n\n  const applyWallpaperPalette = (accentHex: string, isDark: boolean): void => {\n    const targetMode: ThemeMode = isDark ? 'dark' : 'light'\n    const targetTheme = settings[targetMode]\n    if (setModeRole) {\n      setModeRole(targetMode, 'accent', accentHex)\n    } else {\n      set('accent', accentHex)\n    }\n    const palette = derivePalette(accentHex, isDark)\n    for (const [role, hex] of Object.entries(palette)) {\n      if ((targetTheme?.[role as AppearanceRole] ?? settings[role as AppearanceRole]) === '') {\n        if (setModeRole) setModeRole(targetMode, role as AppearanceRole, hex)\n        else set(role as AppearanceRole, hex)\n      }\n    }\n    setActiveMode(targetMode)\n    set('preset', 'custom')\n  }\n\n  const readFile = async (file: File | undefined): Promise<void> => {\n    if (file === undefined) return\n    // Pre-classify the common failures so the hint can say why; the same\n    // guards stay authoritative inside readImageFile.\n    if (!file.type.startsWith('image/')) {\n      setReadError('type')\n      return\n    }\n    if (file.size > MAX_INPUT_BYTES) {\n      setReadError('size')\n      return\n    }\n    setReading(true)\n    setReadError(null)\n    try {\n      const payload = await prepareImage(file)\n      // Store by reference; the settings only carry the record key.\n      const key = await saveImage(payload.blob, file.name)\n      setImage({ url: key, imageDark: payload.imageDark })\n      // Auto-palette: the wallpaper's dominant hue becomes the accent color\n      // and fills the untouched surface roles.\n      if (payload.accent !== null) applyWallpaperPalette(payload.accent, payload.imageDark)\n    } catch {\n      setReadError('read')\n    } finally {\n      setReading(false)\n    }\n  }\n  const readVideo = async (file: File | undefined): Promise<void> => {\n    if (file === undefined) return\n    if (!isVideoFile(file)) {\n      setVideoError('type')\n      return\n    }\n    if (file.size > MAX_VIDEO_BYTES) {\n      setVideoError('size')\n      return\n    }\n    setVideoReading(true)\n    setVideoError(null)\n    try {\n      // Replacing a video must drop the previous IndexedDB record, or the\n      // store accumulates one entry per upload.\n      const oldKey = settings.backgroundVideo\n      if (oldKey !== '') void deleteVideo(oldKey)\n      const key = await saveVideo(file, file.name)\n      setVideo(key)\n    } catch {\n      setVideoError('read')\n    } finally {\n      setVideoReading(false)\n    }\n  }\n  const removeVideo = (): void => {\n    if (settings.backgroundVideo !== '') void deleteVideo(settings.backgroundVideo)\n    setVideo(null)\n  }\n  const loadFromUrl = async (): Promise<void> => {\n    const url = urlDraft.trim()\n    if (url === '') return\n    setUrlReading(true)\n    setUrlError(null)\n    try {\n      if (classifyUrl(url) === 'video') {\n        const file = await loadVideoFromUrl(url)\n        // Replacing a video must drop the previous record (same rule as uploads).\n        const oldKey = settings.backgroundVideo\n        if (oldKey !== '') void deleteVideo(oldKey)\n        const key = await saveVideo(file, file.name)\n        setVideo(key)\n      } else {\n        const payload = await loadImageFromUrl(url)\n        // Store by reference (same rule as uploads).\n        const key = await saveImage(payload.blob, urlToName(url))\n        setImage({ url: key, imageDark: payload.imageDark })\n        // Auto-palette, same rule as uploads.\n        if (payload.accent !== null) applyWallpaperPalette(payload.accent, payload.imageDark)\n      }\n      setUrlDraft('')\n    } catch (error) {\n      setUrlError(error instanceof UrlLoadFailure ? error.code : 'network')\n    } finally {\n      setUrlReading(false)\n    }\n  }\n  const onPick = (event: ChangeEvent<HTMLInputElement>): void => {\n    const file = event.target.files?.[0]\n    event.target.value = ''\n    void readFile(file)\n  }\n  const onPickVideo = (event: ChangeEvent<HTMLInputElement>): void => {\n    const file = event.target.files?.[0]\n    event.target.value = ''\n    void readVideo(file)\n  }\n  const onDrop = (event: DragEvent<HTMLDivElement>): void => {\n    event.preventDefault()\n    setDragging(false)\n    const file = event.dataTransfer.files?.[0]\n    // Route by video-ness (MIME or extension), not MIME alone: empty-MIME\n    // containers like .mkv used to fall into the image path and die there.\n    if (file !== undefined && isVideoFile(file)) void readVideo(file)\n    else void readFile(file)\n  }\n  const changeRole = (role: AppearanceRole, hex: string): void => {\n    const normalized = hex.length === 4 ? formatHex(parseHex(hex)) : hex.toLowerCase()\n    if (setModeRole) {\n      setModeRole(activeMode, role, normalized)\n    } else {\n      set(role, normalized)\n      set('preset', 'custom')\n    }\n  }\n  const onPresetClick = (presetId: string): void => {\n    if (applyModePreset) {\n      applyModePreset(activeMode, presetId)\n    } else {\n      applyPreset(presetId)\n    }\n  }\n  const doExport = async (): Promise<void> => {\n    if (exportTimerRef.current !== null) {\n      clearTimeout(exportTimerRef.current)\n      exportTimerRef.current = null\n    }\n    setExported(false)\n    try {\n      await navigator.clipboard.writeText(exportColorScheme(settings))\n      setExported(true)\n      exportTimerRef.current = setTimeout(() => {\n        setExported(false)\n        exportTimerRef.current = null\n      }, 2500)\n    } catch {\n      setSchemeError(true)\n    }\n  }\n  const doImport = (): void => {\n    setSchemeError(false)\n    try {\n      const parsed = parseColorScheme(schemeDraft)\n      if (parsed.light !== undefined && parsed.dark !== undefined) {\n        if (applyModeColors) {\n          applyModeColors('light', parsed.light)\n          applyModeColors('dark', parsed.dark)\n        } else {\n          applyColors(parsed.dark)\n        }\n      } else {\n        const roleColors: Partial<Record<AppearanceRole, string>> = {}\n        for (const role of APPEARANCE_ROLES) {\n          if (parsed[role] !== undefined) roleColors[role] = parsed[role]\n        }\n        if (applyModeColors) {\n          applyModeColors(activeMode, roleColors)\n        } else {\n          applyColors(roleColors)\n        }\n      }\n      setSchemeOpen(false)\n      setSchemeDraft('')\n    } catch {\n      setSchemeError(true)\n    }\n  }\n\n  return (\n    <div className={css.group}>\n      <DisclosureRow\n        icon={<PersonalizationIcon />}\n        title={t('row.title')}\n        open={open}\n        expandable\n        expandOnRowClick\n        onToggle={() => { setOpen(value => !value) }}\n      >\n        <div className={css.body} onClick={event => { event.stopPropagation() }}>\n          <div className={css.modeSelectorRow}>\n            <div className={css.modeSegmented} role=\"tablist\" aria-label={t('row.title')}>\n              <button\n                type=\"button\"\n                role=\"tab\"\n                aria-selected={activeMode === 'light'}\n                className={clsx(css.modeTab, activeMode === 'light' && css.modeTabActive)}\n                onClick={() => { setActiveMode('light') }}\n              >\n                <span className={css.modeTabIcon}><SunIcon /></span>\n                <span>{t('mode.light')}</span>\n                {currentHostMode === 'light' && <span className={css.activeBadge}>{t('mode.active')}</span>}\n              </button>\n              <button\n                type=\"button\"\n                role=\"tab\"\n                aria-selected={activeMode === 'dark'}\n                className={clsx(css.modeTab, activeMode === 'dark' && css.modeTabActive)}\n                onClick={() => { setActiveMode('dark') }}\n              >\n                <span className={css.modeTabIcon}><MoonIcon /></span>\n                <span>{t('mode.dark')}</span>\n                {currentHostMode === 'dark' && <span className={css.activeBadge}>{t('mode.active')}</span>}\n              </button>\n            </div>\n          </div>\n          <div className={css.hint}>{t('mode.hint' as AppearanceKey)}</div>\n\n          <div className={css.section}>\n            <div className={css.sectionTitle}>{t('presets.title')}</div>\n            <div className={css.chipRow} role=\"group\">\n              {presetsCatalog.map(preset => (\n                <button\n                  key={preset.id}\n                  type=\"button\"\n                  className={clsx(css.chip, activePreset === preset.id && css.chipSelected)}\n                  aria-pressed={activePreset === preset.id}\n                  onClick={() => { onPresetClick(preset.id) }}\n                >\n                  {t(`preset.${preset.id}` as AppearanceKey)}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          <div className={css.section}>\n            <div className={css.sectionTitle}>{t('colors.title')}</div>\n            <div className={css.colorGrid}>\n              {APPEARANCE_ROLES.map(role => (\n                <ColorField\n                  key={`${activeMode}-${role}`}\n                  label={t(`color.${role}` as AppearanceKey)}\n                  value={currentModeTheme?.[role] ?? ''}\n                  stock={STOCK_ROLE_COLORS[activeMode][role]}\n                  onChange={hex => { changeRole(role, hex) }}\n                />\n              ))}\n            </div>\n          </div>\n\n          <div\n            className={clsx(css.section, dragging && css.dragging)}\n            onDragOver={event => { event.preventDefault(); setDragging(true) }}\n            onDragLeave={() => { setDragging(false) }}\n            onDrop={onDrop}\n          >\n            <div className={css.sectionTitle}>{t('background.title')}</div>\n            <div className={css.uploadRow}>\n              <input\n                ref={fileRef}\n                className={css.fileInput}\n                type=\"file\"\n                accept={ACCEPTED_IMAGE_TYPES.join(',')}\n                onChange={onPick}\n              />\n              <button\n                type=\"button\"\n                className={css.ghostButton}\n                disabled={reading}\n                onClick={() => { fileRef.current?.click() }}\n              >\n                {reading\n                  ? t('background.reading')\n                  : settings.backgroundImage === ''\n                    ? t('background.upload')\n                    : t('background.replace')}\n              </button>\n              {settings.backgroundImage !== '' && (\n                <>\n                  <BackgroundThumb token={settings.backgroundImage} />\n                  <button type=\"button\" className={css.ghostButton} onClick={() => { setImage(null) }}>\n                    {t('background.remove')}\n                  </button>\n                </>\n              )}\n              <input\n                ref={videoRef}\n                className={css.fileInput}\n                type=\"file\"\n                accept={ACCEPTED_VIDEO_TYPES.join(',')}\n                onChange={onPickVideo}\n              />\n              <button\n                type=\"button\"\n                className={css.ghostButton}\n                disabled={videoReading}\n                onClick={() => { videoRef.current?.click() }}\n              >\n                {videoReading\n                  ? t('background.reading')\n                  : settings.backgroundVideo !== ''\n                    ? t('background.videoReplace')\n                    : t('background.videoUpload')}\n              </button>\n              {settings.backgroundVideo !== '' && (\n                <button type=\"button\" className={css.ghostButton} onClick={removeVideo}>\n                  {t('background.